post.x-request-examples-text-1:
POST /v3/{project_id}/myactiontemplates/{template_name} HTTP/1.1 
Host: dwr.cn-north-1.myhuaweicloud.com 
Content-Type:application/json 
X-Auth-Token:token
Body: 
{ 
    "category": "<category>", 
    "inputs": [{ 
        "parameter_name": "param1", 
        "default": "TCP", 
        "type": "string", 
        "label": "action1", 
        "constraints": { 
            "valid_values": [ 
                "TCP", 
                "UDP" 
            ] 
        }, 
        "invisible": true, 
        "description": "description param1" 
    }], 
    "dynamic_source_definition": { 
        "param1": { 
            "get_input": "$.inputs.param1" 
        }, 
        "param2": { 
            "get_input": "$.inputs.param2" 
        } 
    }, 
    "need_policy": [{ 
        "version": "1.1", 
        "statement": [{ 
            "action": [ 
                "FunctionGraph:function:invokeAsync", 
                "FunctionGraph:function:invoke", 
                "FunctionGraph:function:updateCode", 
                "FunctionGraph:function:updateConfig", 
                "FunctionGraph:function:create", 
                "FunctionGraph:function:getConfig", 
                "FunctionGraph:function:getCode" 
            ], 
            "resource": [ 
                "FunctionGraph:*:*:function:*" 
            ] 
        }, { 
            "action": [ 
                "MPC:*:*:mpc:*" 
            ] 
        }] 
    }], 
    "description": "" 
}

